mapper.select:

WHERE d.tenant_id = #{tenantId}

  AND d.use_at = 'Y'

ORDER BY d.sort_order ASC, d.department_nm ASC, d.department_id ASC

mapper.update:
UPDATE tb_department
SET use_at = #{useAt},
    updated_by = #{updatedBy,jdbcType=BIGINT},
    updated_at = CURRENT_TIMESTAMP
WHERE department_id = #{departmentId}
  AND tenant_id = #{tenantId}

mapper.select:
SELECT COUNT(*)
FROM tb_department
WHERE tenant_id = #{tenantId}
  AND parent_department_id IS NOT DISTINCT FROM #{parentDepartmentId,jdbcType=BIGINT}
  AND department_nm = #{departmentNm}

  AND department_id != #{excludeDepartmentId}

SELECT COUNT(*)
FROM tb_department
WHERE tenant_id = #{tenantId}
  AND parent_department_id = #{departmentId}
  AND use_at = 'Y'

SELECT COUNT(*)
FROM tb_user u
WHERE u.tenant_id = #{tenantId}
  AND u.department_id = #{departmentId}
  AND u.use_at = 'Y'
  AND NOT (u.retire_dt IS NOT NULL AND u.retire_dt <= CURRENT_DATE)

SELECT EXISTS (
    SELECT 1
    FROM tb_user u
    WHERE u.tenant_id = #{tenantId}
      AND u.user_id = #{userId}
      AND u.department_id = #{departmentId}
      AND u.use_at = 'Y'
      AND NOT (u.retire_dt IS NOT NULL AND u.retire_dt <= CURRENT_DATE)
)
